  var li = e.target.closest('li');
  if (!li) return;
  var id = parseInt(li.dataset.id, 10);

  if (e.target.classList.contains('edit')) {
    if (e.keyCode === ESCAPE_KEY) {
      escapePressed = true;
      editingId = null;
      render();
    } else if (e.keyCode === ENTER_KEY) {
      editTodo(id, e.target.value);
      editingId = null;
      render();
    }
  }
});

dom.todoList.addEventListener('blur', function (e) {
  if (e.target.classList.contains('edit')) {
    var li = e.target.closest('li');
    if (!li) return;
    var id = parseInt(li.dataset.id, 10);
    var value = e.target.value;

    // In real browsers, Escape triggers keydown before blur.
    // In the test harness, blur fires before keydown.
    // Use setTimeout to handle both orderings:
    // - If keydown already set escapePressed, skip the save
    // - If keydown hasn't fired yet, wait for it
    setTimeout(function() {
      if (escapePressed) {
        escapePressed = false;
        return;
      }
      editTodo(id, value);
      editingId = null;
      render();
    }, 0);
  }
}, true);

