dom.todoList.addEventListener('keydown', function (e) {
  var li = e.target.closest('li');
  if (!li) return;
  var id = parseInt(li.dataset.id, 10);

  if (e.target.classList.contains('edit')) {
    if (e.keyCode === ESCAPE_KEY) {
      // Set flag to cancel pending blur save
      escapePressed = true;
      editingId = null;
      render();
    } else if (e.keyCode === ENTER_KEY) {
      editTodo(id, e.target.value);
      editingId = null;
      originalEditValue = null;
      render();
    }
  }
});

dom.todoList.addEventListener('blur', function (e) {
  if (e.target.classList.contains('edit')) {
    var li = e.target.closest('li');
    if (!li) return;
    var id = parseInt(li.dataset.id, 10);
    var value = e.target.value;

    // Defer save to allow keydown to set escapePressed first.
    // In real browsers, keydown fires before blur for Escape.
    // In the test harness, blur fires before keydown, but the
    // setTimeout callback runs after both events complete.
    setTimeout(function() {
      if (escapePressed) {
        escapePressed = false;
        return;
      }
      editTodo(id, value);
      editingId = null;
      originalEditValue = null;
      render();
    }, 0);
  }
}, true);

