function reloadPage(world) {  world.disposeApp();
  world.loadApp();}```

And the After hook:```javascriptAfter(async function () {  if (this.window && this.window.localStorage) {
    const ls = this.window.localStorage;    for (let i = 0; i < ls.length; i++) {      const k = ls.key(i);      sharedLocalStorage[k] = ls.getItem(k);
    }  }
